    border: none;
    border-top: 1px solid var(--color-border);
  }
}
}

@layer astryx-theme {
@scope (:where([data-astryx-theme="r-star"])) to ([data-astryx-theme]) {
  :scope {
    --color-bg: #fff;
  }
}

@scope (:where([data-astryx-theme="c-star"])) to ([data-astryx-theme]) {
  :scope {
    --color-bg: #000;
  }
}

@scope (:where([data-astryx-theme="r-star"], [data-astryx-theme="c-star"])) to ([data-astryx-theme]) {
  [data-astryx-media="dark"] {
    color-scheme: dark;
    --color-text-primary: var(--color-on-dark);
    --color-icon-primary: var(--color-on-dark);
    --color-accent: var(--color-on-dark);
  }

  [data-astryx-media="light"] {
    color-scheme: light;
    --color-text-primary: var(--color-on-light);
    --color-icon-primary: var(--color-on-light);
    --color-accent: var(--color-on-light);
  }
}
}

